import * as React from 'react'
import { Button } from './button.js'
import { Input } from './input.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/** Column definition for the table */
export interface DataTableColumn<T> {
  /** Unique column identifier */
  key: string
  /** Display label */
  header: string
  /** Render cell content — receives the row data */
  render: (item: T) => React.ReactNode
  /** Sort by this field (optional — omit for non-sortable columns) */
  sortKey?: keyof T | ((item: T) => unknown)
  /** Column width class (optional) */
  className?: string
}

/** Props for the DataTable component */
export interface DataTableProps<T> {
  /** Array of data rows to display */
  data: T[]
  /** Column definitions */
  columns: DataTableColumn<T>[]
  /** Current search term (controlled) */
  searchTerm: string
  /** Search callback — called with new search term */
  onSearchChange: (term: string) => void
  /** Total number of items (for pagination footer) */
  totalItems: number
  /** Current page number (1-indexed) */
  currentPage: number
  /** Items per page */
  pageSize: number
  /** Page change callback */
  onPageChange: (page: number) => void
  /** Loading state */
  isLoading?: boolean
  /** Empty state message */
  emptyMessage?: string
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function DataTable<T extends Record<string, unknown>>({
  data,
  columns,
  searchTerm,
  onSearchChange,
  totalItems,
  currentPage,
  pageSize,
  onPageChange,
  isLoading = false,
  emptyMessage = 'No items found',
}: DataTableProps<T>) {
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize))

  return (
    <div className="space-y-4">
      {/* Search bar */}
      <div className="flex items-center gap-3">
        <Input
          type="text"
          placeholder="Search..."
          value={searchTerm}
          onChange={(e) => onSearchChange(e.target.value)}
          className="max-w-sm"
        />
      </div>

      {/* Table */}
      <div className="overflow-x-auto rounded border">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b bg-muted/30">
              {columns.map((col) => (
                <th
                  key={col.key}
                  className={`px-4 py-2 text-left font-medium text-muted-foreground ${col.className ?? ''}`}
                >
                  {col.header}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {isLoading ? (
              <tr>
                <td colSpan={columns.length} className="px-4 py-8 text-center text-muted-foreground">
                  Loading...
                </td>
              </tr>
            ) : data.length === 0 ? (
              <tr>
                <td colSpan={columns.length} className="px-4 py-8 text-center text-muted-foreground">
                  {emptyMessage}
                </td>
              </tr>
            ) : (
              data.map((item, index) => (
                <tr key={(item as any).id ?? index} className={`border-b hover:bg-muted/20 transition-colors ${index % 2 === 0 ? '' : 'bg-muted/10'}`}>
                  {columns.map((col) => (
                    <td key={col.key} className={`px-4 py-2 ${col.className ?? ''}`}>
                      {col.render(item)}
                    </td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination footer */}
      <div className="flex items-center justify-between text-sm text-muted-foreground">
        <span>
          Showing {(currentPage - 1) * pageSize + 1}–{Math.min(currentPage * pageSize, totalItems)} of {totalItems}
        </span>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => onPageChange(currentPage - 1)}
            disabled={currentPage <= 1 || isLoading}
          >
            Previous
          </Button>
          <span className="px-2">
            {currentPage} / {totalPages}
          </span>
          <Button
            variant="outline"
            size="sm"
            onClick={() => onPageChange(currentPage + 1)}
            disabled={currentPage >= totalPages || isLoading}
          >
            Next
          </Button>
        </div>
      </div>
    </div>
  )
}

import { NavLink } from 'react-router-dom'
import { useAppStore } from '@/app/store'
import {
  ChevronLeft,
  ChevronRight,
  Home,
  ReceiptText,
  PackageSearch,
  Package,
  Users,
  Wrench,
  type LucideIcon,
} from 'lucide-react'
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@radix-ui/react-tooltip'

const navItems = [
  { to: '/', icon: Home, label: 'Home' },
  { to: '/pos', icon: ReceiptText, label: 'POS' },
  { to: '/sales', icon: ReceiptText, label: 'Sales History' },
  { to: '/customers', icon: Users, label: 'Customers' },
  { to: '/repairs', icon: Wrench, label: 'Repairs' },
  { to: '/catalog/parts', icon: Package, label: 'Catalog' },
  { to: '/products/dst-search', icon: PackageSearch, label: 'Product Finder' },
]

export function SidePanel() {
  const { sidebarOpen, toggleSidebar } = useAppStore()

  return (
    <TooltipProvider delayDuration={0}>
      <aside
        className={`border-r bg-card transition-all duration-200 overflow-hidden ${
          sidebarOpen ? 'w-64' : 'w-12'
        }`}
      >
        {/* Collapse toggle — vertically centered in its area */}
        <div className="flex items-center justify-start px-2">
          {sidebarOpen && (
            <button
              onClick={toggleSidebar}
              className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground"
            >
              <ChevronLeft size={16} />
              Collapse
            </button>
          )}
          {!sidebarOpen && (
            <div className="flex h-full flex-col justify-center py-4">
              <button
                onClick={toggleSidebar}
                className="flex items-center justify-center text-muted-foreground hover:text-foreground"
              >
                <ChevronRight size={16} />
              </button>
            </div>
          )}
        </div>
        <nav className="mt-4">
          <NavItemList items={navItems} sectionTitle="Main" sidebarOpen={sidebarOpen} />
        </nav>
      </aside>
    </TooltipProvider>
  )
}

function NavItem({ to, icon: Icon, label, sidebarOpen }: {
  to: string
  icon: LucideIcon
  label: string
  sidebarOpen: boolean
}) {
  return (
    <NavLink
      to={to}
      className={({ isActive }) =>
        `flex items-center gap-2 px-4 py-2 text-sm ${
          sidebarOpen
            ? `rounded ${
                isActive ? 'bg-primary text-primary-foreground'
                  : 'text-muted-foreground hover:bg-muted/50'
              }`
            : `${
                isActive ? 'border-l-[3px] border-primary pl-2 pr-4 text-primary font-medium'
                  : 'text-muted-foreground hover:text-foreground'
              }`
        }`
      }
    >
      <Tooltip>
        <TooltipTrigger asChild>
          <Icon size={16} />
        </TooltipTrigger>
        <TooltipContent side="right">
          <p>{label}</p>
        </TooltipContent>
      </Tooltip>
      {sidebarOpen && label}
    </NavLink>
  )
}

function NavItemList({ items, sectionTitle, sidebarOpen }: {
  items: { to: string; icon: LucideIcon; label: string }[]
  sectionTitle: string
  sidebarOpen: boolean
}) {
  return (
    <>
      {sidebarOpen && (
        <h2 className="px-4 text-xs font-semibold uppercase text-muted-foreground">
          {sectionTitle}
        </h2>
      )}
      <ul className="space-y-2">
        {items.map((item) => (
          <li key={item.to}>
            <NavItem to={item.to} icon={item.icon} label={item.label} sidebarOpen={sidebarOpen} />
          </li>
        ))}
      </ul>
      {sidebarOpen && <hr className="my-4 border-t border-muted" />}
    </>
  )
}

#!/usr/bin/env python3
"""
Maestro Dashboard — Interactive Terminal UI for Orchestrator Monitoring.

A 6-tab TUI system with LazyGit/k9s styling:
- Issues (GitHub open issues)
- Sessions (local session browser)
- Pipelines (pipeline monitoring)
- Chat (LLM chat modal overlay)
- Logs (JSONL log tailing)
- Agents (flow phase status)

Usage:
    cd .pi/maestro && python3 dashboard.py
"""

import os
import sys
import traceback
from pathlib import Path

_LOG_DIR = Path(__file__).parent / "temp"
_LOG_DIR.mkdir(exist_ok=True, parents=True)
_DEBUG_LOG = _LOG_DIR / "dashboard.log"

def _sync(msg: str) -> None:
    """Write synchronously to log file using os.write — guaranteed to hit disk even on crash."""
    try:
        from datetime import datetime
        ts = datetime.now().strftime("%H:%M:%S.%f")[:-3]
        line = f"[{ts}] APP     {msg}\n"
        fd = os.open(str(_DEBUG_LOG), os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o644)
        os.write(fd, line.encode())
        os.close(fd)
    except Exception:
        pass

def _sync_err(exc: BaseException) -> None:
    """Write exception + traceback synchronously."""
    try:
        from datetime import datetime
        ts = datetime.now().strftime("%H:%M:%S.%f")[:-3]
        fd = os.open(str(_DEBUG_LOG), os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o644)
        os.write(fd, f"[{ts}] APP     ERROR: {exc}\n".encode())
        for line in traceback.format_tb(exc.__traceback__):
            os.write(fd, line.encode())
        os.close(fd)
    except Exception:
        pass

def _eprint(msg: str) -> None:
    """Print to stderr + write sync log."""
    _sync(msg)

from textual.app import App, ComposeResult
from textual.binding import Binding
from textual.containers import Container, Horizontal, Vertical
from textual.widgets import (
    DataTable,
    Footer,
    Header,
    Label,
    Select,
    Static,
    TabbedContent,
    TabPane,
)
from textual.reactive import reactive
from panels.session_browser_panel import SessionBrowserPanel, SessionSelected
from panels.replay_modal import ReplayModal
from panels.session_files_modal import SessionFilesModal
from panels.raw_logs_modal import RawLogsModal
from panels.pipeline_monitor_panel import PipelineMonitorPanel


class MaestroApp(App):
    """Maestro Dashboard — 6-tab TUI with horizontal split layout."""

    TITLE = "Maestro Dashboard"
    SUBTITLE = "GitHub Issues • Sessions • Pipelines • Chat • Logs • Agents"

    CSS = """
    /* ── Screen ─────────────────────────────────────────────────────── */
    Screen {
        background: $boost;
    }

    /* ── Tab styling (LazyGit/k9s inspired) ─────────────────────────── */
    TabbedContent {
        height: auto;
    }

    TabbedContent > .tab-bar {
        background: $primary-darken-2;
        color: $text-muted;
    }

    TabbedContent > .tab-bar > .tab--label {
        text-style: bold;
    }

    /* ── Filters bar ────────────────────────────────────────────────── */
    #filters-bar {
        dock: top;
        height: 3;
        margin-top: 0;
        padding: 0 2;
        background: $surface-darken-1;
        border-bottom: solid $secondary;
    }

    /* ── Main horizontal split ──────────────────────────────────────── */
    #main-split {
        layout: horizontal;
        height: 1fr;
        margin-top: 1;
    }

    #list-view {
        width: 65%;
        height: auto;
        border: solid $primary;
        background: $surface;
    }

    #detail-panel {
        width: 35%;
        border-left: solid $secondary;
        background: $surface-darken-2;
        padding: 1 2;
    }

    /* ── DataTable styling ──────────────────────────────────────────── */
    DataTable {
        height: 1fr;
    }

    DataTable > .data-table--header {
        background: $primary-darken-1;
        color: white;
        text-style: bold;
    }

    DataTable > .data-table--fixed-header {
        background: $primary-darken-2;
    }

    /* ── Placeholder / empty states ─────────────────────────────────── */
    .placeholder {
        width: 1fr;
        height: 1fr;
        content-align: center middle;
        color: $text-muted;
    }

    /* ── Detail section headers ─────────────────────────────────────── */
    .detail-header {
        text-style: bold;
        color: $accent;
        margin-bottom: 1;
    }

    .detail-label {
        color: $text-muted;
        width: auto;
    }

    /* ── Loading indicator ──────────────────────────────────────────── */
    #loading-indicator {
        content-align: center middle;
        color: $warning;
    }

    /* ── Error banner (overlay) ─────────────────────────────────────── */
    #error-banner {
        layer: overlay;
        dock: bottom;
        display: none;
        width: 1fr;
        height: auto;
        background: $error-darken-2;
        border: round $error;
        padding: 0 2;
    }

    #error-banner.visible {
        display: block;
    }

    /* ── Footer ─────────────────────────────────────────────────────── */
    Footer {
        background: $primary-darken-1;
        color: white;
    }
    """

    BINDINGS = [
        Binding("q", "quit", "Quit"),
        Binding("r", "refresh_issues_or_replay", "Refresh/Replay"),
        Binding("g", "open_github", "Open GitHub"),
        Binding("s", "start_flow", "Start Flow"),
        Binding("/", "focus_search", "Search"),
    ]



    # Session tracking for context-aware keybindings
    _selected_session_path: str | None = None

    # ── Reactive state ────────────────────────────────────────────────
    active_tab: str = "issues"
    selected_issue_number: int | None = None
    _loading_issues: bool = False
    _selected_labels: list[str] = ["needs-triage", "parent-prd"]
    # Sessions state
    _sessions_loaded: bool = False

    def __init__(self, api_override=None):
        super().__init__()
        self._api_override = api_override  # For testing
        self._dashboard_api = None  # Lazy-initialized DashboardAPI

    @property
    def dashboard_api(self):
        """Lazy-initialized DashboardAPI."""
        if self._api_override is not None:
            return self._api_override
        if self._dashboard_api is None:
            from lib.dashboard_api import DashboardAPI

            self._dashboard_api = DashboardAPI()
        return self._dashboard_api

    # ── Compose ───────────────────────────────────────────────────────
    def compose(self) -> ComposeResult:
        """Build the 6-tab layout with horizontal split."""
        _eprint("[COMPOSE] Starting...")
        yield Header()

        # Filters bar — label filter dropdown
        with Container(id="filters-bar"):
            with Horizontal():
                yield Label("Labels: ")
                yield Select(
                    options=[("needs-triage", "needs-triage"), ("parent-prd", "parent-prd")],
                    prompt="Select labels…",
                    id="label-filter",
                )

        with Horizontal(id="main-split"):
            # ── Left Panel (~65%): Tab content + List View ──────────────
            with Container(id="list-view"):
                with TabbedContent(initial="issues", id="tabs"):
                    # TAB 1: Issues
                    with TabPane("Issues", id="issues"):
                        yield DataTable(id="issue-table")

                    # TAB 2: Sessions
                    with TabPane("Sessions", id="sessions"):
                        yield SessionBrowserPanel(id="session-browser")

                    # TAB 3: Pipelines
                    _sync("[COMPOSE] About to compose PipelineMonitorPanel...")
                    try:
                        with TabPane("Pipelines", id="pipelines"):
                            yield PipelineMonitorPanel(id="pipeline-monitor-panel")
                        _sync("[COMPOSE] PipelineMonitorPanel yielded OK")
                    except Exception as e:
                        _sync(f"[COMPOSE] ERROR in Pipelines tab: {type(e).__name__}: {e}")
                        traceback.print_exc(file=sys.stderr)
                        raise

                    # TAB 4: Chat (stub)
                    with TabPane("Chat", id="chat"):
                        yield Static(
                            "[dim]LLM chat modal overlay — coming in Phase 2[/]",
                            classes="placeholder",
                        )

                    # TAB 5: Logs (stub)
                    with TabPane("Logs", id="logs"):
                        yield Static(
                            "[dim]JSONL log tailing — coming in Phase 2[/]",
                            classes="placeholder",
                        )

                    # TAB 6: Agents (stub)
                    with TabPane("Agents", id="agents"):
                        yield Static(
                            "[dim]Agent roster — coming in Phase 2[/]",
                            classes="placeholder",
                        )

            # ── Right Panel (~35%): Detail View ────────────────────────
            with Vertical(id="detail-panel"):
                yield Label("[bold cyan]Issue Details[/]", id="detail-title")
                yield Static(
                    "[dim]Select an issue from the list to view details.[/]",
                    id="detail-body",
                )

        # Error banner overlay (hidden by default)
        with Container(id="error-banner"):
            yield Label("[bold red]Error loading issues[/]")

        yield Footer()

