#!/usr/bin/env python3
"""
session_reader.py — Parse JSONL session logs into human-readable summaries.

Adapted from the shared TypeScript session-parser library to provide structured
summaries of Pi agent sessions for terminal display and phase comments.

Extracts: file operations, errors, model metadata, duration, and key events.

Usage:
    summary = parse_session_log("/tmp/sessions/abc123.jsonl")
    print(format_session_summary(summary))  # Human-readable string
"""

import json
from pathlib import Path
from typing import Optional


def _to_epoch_ms(ts) -> Optional[int]:
    """Convert an ISO timestamp or epoch ms to epoch milliseconds."""
    if ts is None:
        return None

    if isinstance(ts, (int, float)):
        # Already numeric — check if it's already ms (epoch > 1e12 means ms)
        if ts > 1e12:
            return int(ts)
        else:
            return int(ts * 1000)  # Assume seconds

    try:
        # Try parsing as ISO string
        from datetime import datetime
        dt = datetime.fromisoformat(str(ts).replace('Z', '+00:00'))
        return int(dt.timestamp() * 1000)
    except (ValueError, TypeError):
        return None


def _extract_text_from_content(content) -> str:
    """Extract plain text from tool result content (array of parts or scalar)."""
    if not content:
        return ""

    if isinstance(content, str):
        return content

    if isinstance(content, list):
        texts = [
            part.get("text", "") 
            for part in content 
            if isinstance(part, dict) and part.get("type") == "text"
        ]
        return "\n".join(texts)

    return str(content)


def parse_session_log(log_path: str) -> dict:
    """
    Parse a JSONL session log and return a structured summary.

    Args:
        log_path: Path to the JSONL session file

    Returns:
        Dict with keys:
            - model (str): Model used in the session
            - duration_seconds (float): Total time from start to end  
            - file_operations (list[dict]): File operations performed
            - errors (list[dict]): Errors encountered
            - events (list[str]): Human-readable event descriptions
    """
    result = {
        "model": None,
        "duration_seconds": 0.0,
        "file_operations": [],
        "errors": [],
        "events": []
    }

    try:
        path = Path(log_path)
        if not path.exists():
            result["events"].append(f"⚠️  Session log file not found: {log_path}")
            return result

        # Track state for pairing tool calls with results
        pending_tool_calls = {}  # toolCallId -> {toolName, arguments}
        first_ts_ms = None
        last_ts_ms = None
        model_name = None

        with open(log_path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue

                try:
                    event = json.loads(line)
                except (json.JSONDecodeError, ValueError):
                    continue

                # Extract timestamp
                ts_ms = _to_epoch_ms(event.get("timestamp")) or _to_epoch_ms(
                    event.get("message", {}).get("timestamp")
                )

                if ts_ms:
                    if first_ts_ms is None or ts_ms < first_ts_ms:
                        first_ts_ms = ts_ms
                    if last_ts_ms is None or ts_ms > last_ts_ms:
                        last_ts_ms = ts_ms

                # Track model info from metadata events
                event_type = event.get("type", "")

                if event_type == "model_change":
                    provider = event.get("provider", "")
                    model_id = event.get("modelId", "")
                    if provider and model_id:
                        model_name = f"{provider}/{model_id}"
                    elif model_id:
                        model_name = model_id

                # Process messages
                message = event.get("message")
                if not message or "role" not in message:
                    continue

                role = message["role"]

                # Handle assistant messages with tool calls
                if role == "assistant":
                    content_parts = message.get("content", [])

                    for part in (content_parts if isinstance(content_parts, list) else []):
                        if not isinstance(part, dict):
                            continue

                        part_type = part.get("type", "")

                        # Track tool calls
                        if part_type == "toolCall":
                            call_id = part.get("id")
                            tool_name = part.get("name", "")
                            args = part.get("arguments", {}) or {}

                            pending_tool_calls[call_id] = {
                                "toolName": tool_name,
                                "arguments": args
                            }

                        # Detect errors in assistant text
                        elif part_type == "text":
                            text = part.get("text", "")
                            if isinstance(text, str):
                                lower_text = text.lower()

                                # Detect decision patterns (from TS implementation)
                                if any(pattern in lower_text for pattern in [
                                    "✅ **", "locked in", "option a:", "option b:"
                                ]):
                                    result["events"].append(f"🔑 Decision: {text[:100]}")

                                # Detect errors/failures in text
                                elif any(w in lower_text for w in ["error:", "failed", "exception"]):
                                    if len(text) > 50:
                                        result["errors"].append({
                                            "type": "assistant_error",
                                            "message": text[:200]
                                        })

                # Handle tool results (success/failure)
                elif role == "toolResult":
                    call_id = message.get("toolCallId") or message.get("parentId")
                    is_error = message.get("isError", False)

                    # Find the original tool call to get name and file path
                    call_info = pending_tool_calls.pop(call_id, None) if call_id else None

                    if call_info:
                        tool_name = call_info["toolName"]
                        args = call_info.get("arguments", {}) or {}

                        # Extract file path from arguments (common in write_file, edit, read, etc.)
                        file_path = args.get("path") or args.get("file") or args.get("filePath") or "unknown"

                        error_content = _extract_text_from_content(message.get("content"))

                        op = {
                            "tool": tool_name.upper(),
                            "path": file_path,
                            "status": "failed" if is_error else "success",
                            "timestamp": ts_ms or "",
                            "error_message": error_content[:200] if is_error and error_content else None
                        }

                        result["file_operations"].append(op)

                        # Add to events for display
                        status_icon = "❌" if is_error else "✅"
                        result["events"].append(
                            f"{status_icon} {tool_name}: {file_path}"
                        )

                        # Track errors
                        if is_error and error_content:
                            result["errors"].append({
                                "type": "tool_error",
                                "message": error_content[:200],
                                "context": f"{tool_name} on {file_path}"
                            })

                    elif is_error and call_id not in pending_tool_calls:
                        # Orphan failure (result with no matching tool call)
                        error_content = _extract_text_from_content(message.get("content"))
                        if error_content:
                            result["errors"].append({
                                "type": "orphan_error",
                                "message": error_content[:200],
                                "context": f"Orphan tool result {event.get('id', 'unknown')}"
                            })

        # Calculate duration
        if first_ts_ms and last_ts_ms:
            result["duration_seconds"] = (last_ts_ms - first_ts_ms) / 1000.0

        # Add model info to events
        if model_name:
            result["model"] = model_name
            result["events"].insert(0, f"🤖 Model: {model_name}")

        # Add duration summary
        if result["duration_seconds"]:
            mins = int(result["duration_seconds"] // 60)
            secs = int(result["duration_seconds"] % 60)
            event_line = f"⏱️  Session lasted {mins}m {secs}s"
            if model_name:
                event_line += f" ({model_name})"
            result["events"].insert(1, event_line)

        # Add file operation summary (if any)
        successful_ops = [op for op in result["file_operations"] if op["status"] == "success"]
        failed_ops = [op for op in result["file_operations"] if op["status"] == "failed"]

        if successful_ops:
            result["events"].append(f"📄 {len(successful_ops)} file(s) written successfully")
        if failed_ops:
            result["events"].append(f"❌ {len(failed_ops)} file operation(s) failed")

        # Add error summary (if any)
        if result["errors"]:
            result["events"].append(f"⚠️  {len(result['errors'])} error(s) detected")

    except Exception as e:
        result["events"].append(f"⚠️  Failed to parse session log: {e}")

    return result


def format_session_summary(summary: dict) -> str:
    """Format a session summary into a readable string block."""
    lines = []

    for event in summary.get("events", []):
        lines.append(f"   • {event}")

    if summary.get("errors"):
        lines.append("")
        lines.append("   ⚠️  Errors:")
        for err in summary["errors"][:3]:  # Limit to first 3 errors
            lines.append(f"      - [{err['type']}] {err['message'][:100]}")

    if summary.get("file_operations"):
        lines.append("")
        lines.append("   📋 File Operations:")
        for op in summary["file_operations"][:5]:  # Limit to first 5
            status = "✅" if op["status"] == "success" else "❌"
            lines.append(f"      {status} {op['tool']}: {op['path']}")

    return "\n".join(lines)

#!/usr/bin/env python3
"""
ReplayModal — Step-through JSONL event playback for a session.

Opens when user presses `[r]` on a selected session row in the Sessions tab.
Shows each JSONL event one-by-one with navigation controls:
- `←` / `→` or `h` / `l` — Navigate prev/next event
- `Home` / `End` / `g` / `G` — Jump to first/last event
- `Space` — Toggle auto-play (auto-advance every 300ms)
- `Esc` / `q` — Close modal

Usage:
    from panels.replay_modal import ReplayModal
    screen = app.push_screen(ReplayModal(session_path, events))
"""

import json
from pathlib import Path
from textual.app import ComposeResult
from textual.binding import Binding
from textual.containers import Center, Horizontal, Vertical
from textual.screen import ModalScreen
from textual.widgets import (
    Button,
    Label,
    Static,
)


class ReplayModal(ModalScreen):
    """Modal overlay for step-through JSONL event playback.

    Attributes:
        session_path: Path to the JSONL session file.
        events: List of parsed JSON dict objects from the session log.
    """

    BINDINGS = [
        Binding("left", "prev_event", "Prev"),
        Binding("right", "next_event", "Next"),
        Binding("h", "prev_event", "Prev"),
        Binding("l", "next_event", "Next"),
        Binding("home", "first_event", "First"),
        Binding("end", "last_event", "Last"),
        Binding("g", "first_event", "First"),
        Binding("G", "last_event", "Last"),
        Binding("space", "toggle_autoplay", "Auto-play"),
        Binding("escape", "dismiss_modal", "Close"),
        Binding("q", "dismiss_modal", "Quit"),
    ]

    CSS = """
    ReplayModal {
        align: center middle;
        background: $background 70%;
    }

    #replay-container {
        width: 80;
        height: 70%;
        border: round $accent;
        background: $surface-darken-2;
        padding: 1 2;
    }

    #replay-title {
        text-align: center;
        text-style: bold;
        color: $accent;
        margin-bottom: 1;
    }

    #event-display {
        width: 100%;
        height: 1fr;
        border: solid $secondary;
        background: $surface-darken-3;
        padding: 1 2;
        overflow-y: auto;
        margin-bottom: 1;
    }

    #event-display .json-key {
        color: $primary;
    }

    #event-display .json-string {
        color: $success;
    }

    #event-display .json-number {
        color: $warning;
    }

    #replay-controls {
        height: 4;
        dock: bottom;
        layout: horizontal;
        align-horizontal: center;
    }

    #btn-prev, #btn-next, #btn-first, #btn-last, #btn-autoplay {
        margin: 0 1;
    }

    #event-counter {
        width: auto;
        color: $text-muted;
        margin: 0 2;
        align: center middle;
    }

    .autoplay-active {
        text-style: bold;
        color: $success;
    }
    """

    def __init__(self, session_path: str, events: list[dict], **kwargs):
        super().__init__(**kwargs)
        self.session_path = Path(session_path)
        self.events = events or []
        self._current_index = 0
        self._autoplaying = False

    def compose(self) -> ComposeResult:
        """Build the replay modal layout."""
        with Center():
            with Vertical(id="replay-container"):
                yield Label(
                    f"[bold cyan]Replay[/bold cyan] — "
                    f"{self.session_path.name} ({len(self.events)} events)",
                    id="replay-title",
                )

                # Event display area
                yield Static(
                    "[dim]Select an event to view details.[/]",
                    id="event-display",
                )

                # Navigation controls
                with Horizontal(id="replay-controls"):
                    yield Button("⏮ First", id="btn-first")
                    yield Label(f"0 / {len(self.events)}", id="event-counter")
                    yield Button("⏭ Last", id="btn-last")
                    yield Button("◀ Prev", id="btn-prev")
                    yield Button("Next ▶", id="btn-next")
                    yield Label("[dim]Auto-play[/]", id="autoplay-label")

    def on_mount(self) -> None:
        """Initialize the display with the first event."""
        self._render_event(0)

    # ── Navigation Actions ──────────────────────────────────────────────

    def action_prev_event(self) -> None:
        """Navigate to the previous event."""
        if self.events and self._current_index > 0:
            self._current_index -= 1
            self._render_event(self._current_index)

    def action_next_event(self) -> None:
        """Navigate to the next event."""
        if self.events and self._current_index < len(self.events) - 1:
            self._current_index += 1
            self._render_event(self._current_index)

    def action_first_event(self) -> None:
        """Jump to the first event."""
        if self.events:
            self._current_index = 0
            self._render_event(0)

    def action_last_event(self) -> None:
        """Jump to the last event."""
        if self.events:
            self._current_index = len(self.events) - 1
            self._render_event(self._current_index)

    def action_toggle_autoplay(self) -> None:
        """Toggle auto-play mode (auto-advance every 300ms)."""
        self._autoplaying = not self._autoplaying
        autoplay_label = self.query_one("#autoplay-label", Label)
        if self._autoplaying:
            autoplay_label.set_class("autoplay-active")
            autoplay_label.update("[bold green]▶ Auto-play[/]")
            # Start auto-advance interval
            self.set_interval(0.3, self._auto_advance)
        else:
            autoplay_label.remove_class("autoplay-active")
            autoplay_label.update("[dim]Auto-play[/]")
            self.clear_interval(self._auto_advance)

    def _auto_advance(self) -> None:
        """Advance to the next event (called by auto-play interval)."""
        if not self.events:
            return
        if self._current_index < len(self.events) - 1:
            self._current_index += 1
            self._render_event(self._current_index)
        else:
            # Reached end — stop autoplay
            self.action_toggle_autoplay()

    def action_dismiss_modal(self) -> None:
        """Close the modal and return focus."""
        if self._autoplaying:
            self.clear_interval(self._auto_advance)
        self.dismiss(None)

    # ── Rendering ───────────────────────────────────────────────────────

    def _render_event(self, index: int) -> None:
        """Render a single JSONL event in the display area.

        Args:
            index: Index of the event to render.
        """
        if not self.events or index < 0 or index >= len(self.events):
            return

        event = self.events[index]
        display = self.query_one("#event-display", Static)

        # Build a formatted representation of the event
        lines = [f"[bold cyan]Event {index + 1} / {len(self.events)}[/]\n"]

        # Show type first (most important field)
        event_type = event.get("type", "unknown")
        timestamp = event.get("timestamp", "")

        if event_type == "message":
            msg = event.get("message", {})
            role = msg.get("role", "?")
            content_parts = msg.get("content", [])

            lines.append(f"[bold]Type:[/bold] {event_type}")
            lines.append(f"[dim]Role:[/dim] {role}")
            if timestamp:
                lines.append(f"[dim]Time:[/dim] {timestamp}")

            # Extract text content
            texts = []
            for part in (content_parts if isinstance(content_parts, list) else []):
                if isinstance(part, dict):
                    part_type = part.get("type", "")
                    if part_type == "text":
                        text = part.get("text", "")
                        if isinstance(text, str):
                            texts.append(text)

            if texts:
                combined_text = "\n".join(texts)
                # Truncate long messages for display
                if len(combined_text) > 2000:
                    combined_text = combined_text[:2000] + "...\n[truncated]"
                lines.append(f"\n[dim]Content:[/dim]\n{combined_text}")

            # Show model info if present
            api_info = msg.get("api", "") or msg.get("provider", "") or ""
            model = msg.get("model", "") or ""
            if api_info:
                lines.append(f"\n[dim]API:[/dim] {msg.get('api', '')} | [dim]Model:[/dim] {model}")

        elif event_type == "toolCall":
            # This might be nested in a message — handle at top level too
            tool_name = event.get("name", "") or event.get("message", {}).get("name", "")
            args = event.get("arguments", {}) or event.get("message", {}).get("arguments", {})
            lines.append(f"[bold]Type:[/bold] {event_type}")
            if tool_name:
                lines.append(f"[dim]Tool:[/dim] {tool_name}")
            if args:
                lines.append(f"[dim]Args:[/dim] {json.dumps(args, default=str)[:500]}")

        elif event_type == "model_change":
            provider = event.get("provider", "")
            model_id = event.get("modelId", "")
            lines.append(f"[bold]Type:[/bold] Model Change")
            if provider:
                lines.append(f"[dim]Provider:[/dim] {provider}")
            if model_id:
                lines.append(f"[dim]Model:[/dim] {model_id}")

        elif event_type == "toolResult":
            tool_call_id = event.get("toolCallId", "") or event.get("parentId", "")
            is_error = event.get("isError", False)
            content = event.get("content", "")
            lines.append(f"[bold]Type:[/bold] {event_type}")
            if tool_call_id:
                lines.append(f"[dim]Tool Call ID:[/dim] {tool_call_id}")
            status = "❌ ERROR" if is_error else "✅ Success"
            lines.append(f"[bold]{status}[/]")
            if content:
                text_content = self._extract_text_from_content(content)
                if len(text_content) > 500:
                    text_content = text_content[:500] + "...\n[truncated]"
                lines.append(f"\n[dim]Content:[/dim]\n{text_content}")

        else:
            # Generic event — show as compact JSON
            lines.append(f"[bold]Type:[/bold] {event_type}")
            if timestamp:
                lines.append(f"[dim]Time:[/dim] {timestamp}")
            # Show a compact representation of remaining fields
            filtered = {k: v for k, v in event.items()
                        if k not in ("type", "timestamp") and v is not None}
            if filtered:
                lines.append(f"\n[dim]Data:[/dim]\n{json.dumps(filtered, default=str, indent=2)[:800]}")

        display.update("\n".join(lines))

        # Update counter
        counter = self.query_one("#event-counter", Label)
        counter.update(f"{index + 1} / {len(self.events)}")

    @staticmethod
    def _extract_text_from_content(content) -> str:
        """Extract plain text from tool result content."""
        if not content:
            return ""
        if isinstance(content, str):
            return content
        if isinstance(content, list):
            texts = [
                part.get("text", "")
                for part in content
                if isinstance(part, dict) and part.get("type") == "text"
            ]
            return "\n".join(texts)
        return str(content)

    # ── Button Handlers ─────────────────────────────────────────────────

    def on_button_pressed(self, message: Button.Pressed) -> None:
        """Handle button presses for navigation."""
        btn_id = message.button.id
        if btn_id == "btn-prev":
            self.action_prev_event()
        elif btn_id == "btn-next":
            self.action_next_event()
        elif btn_id == "btn-first":
            self.action_first_event()
        elif btn_id == "btn-last":
            self.action_last_event()
        elif btn_id == "btn-autoplay":
            self.action_toggle_autoplay()

#!/usr/bin/env python3
"""
IssuesPanel — Interactive GitHub Issues panel with expand/collapse detail.

Pure UI panel that receives data from DashboardAPI and renders it.
No direct I/O - all data comes through the API layer.

Features:
- DataTable showing issue number, title, labels, and age
- Click any row to expand/collapse a detail drawer below the table
- Detail view shows full PRD body, acceptance criteria, and parent-child links
"""

from textual.events import Event
from textual.widgets import DataTable, Label
from textual.containers import Vertical
from datetime import datetime, timezone


class IssueSelected(Event):
    """Emitted when an issue row is selected.

    Attributes:
        issue_number: The GitHub issue number that was selected.
    """
    def __init__(self, issue_number: int) -> None:
        super().__init__()
        self.issue_number = issue_number


class IssuesPanel(Vertical):
    """Left panel showing open GitHub issues with expandable detail views."""

    CSS = '''
    IssuesPanel {
        width: 100%;
        height: 100%;
        border: solid $primary;
        background: $surface;
        padding: 1;
        layout: vertical;
    }

